        if(preorder[i] > maxi || preorder[i] < mini)
            return NULL;

        TreeNode* root = new TreeNode(preorder[i++]);

        root -> left = solve(mini, root -> val, preorder, i);
        root -> right = solve(root -> val, maxi, preorder, i);

        return root;
    }

